from datetime import date, datetime
from decimal import Decimal, InvalidOperation, localcontext


def aging_buckets(invoices: list[dict], as_of: date) -> dict[str, Decimal]:
    if isinstance(as_of, datetime):
        as_of_date = as_of.date()
    elif isinstance(as_of, date):
        as_of_date = as_of
    elif isinstance(as_of, str):
        try:
            as_of_date = date.fromisoformat(as_of)
        except ValueError:
            raise ValueError('invalid as_of') from None
    else:
        raise ValueError('invalid as_of')
    if invoices is None:
        raise ValueError('invalid invoices')
    buckets = {'current': Decimal('0.00'), '1-30': Decimal('0.00'), '31-60': Decimal('0.00'), '61-90': Decimal('0.00'), '90+': Decimal('0.00')}
    with localcontext() as ctx:
        ctx.prec = 60
        for invoice in invoices:
            if not isinstance(invoice, dict):
                raise ValueError('invalid invoice')
            if 'due_date' not in invoice or 'amount' not in invoice:
                raise ValueError('missing invoice field')
            raw_due = invoice['due_date']
            if isinstance(raw_due, datetime):
                due_date = raw_due.date()
            elif isinstance(raw_due, date):
                due_date = raw_due
            elif isinstance(raw_due, str):
                try:
                    due_date = date.fromisoformat(raw_due)
                except ValueError:
                    raise ValueError('invalid due_date') from None
            else:
                raise ValueError('invalid due_date')
            raw_amount = invoice['amount']
            if isinstance(raw_amount, bool) or isinstance(raw_amount, float):
                raise ValueError('invalid amount')
            elif isinstance(raw_amount, Decimal):
                amount = raw_amount
            elif isinstance(raw_amount, int):
                amount = Decimal(raw_amount)
            elif isinstance(raw_amount, str):
                try:
                    amount = Decimal(raw_amount)
                except (InvalidOperation, ValueError):
                    raise ValueError('invalid amount') from None
            else:
                raise ValueError('invalid amount')
            if not amount.is_finite():
                raise ValueError('invalid amount')
            days_overdue = (as_of_date - due_date).days
            if days_overdue <= 0:
                key = 'current'
            elif days_overdue <= 30:
                key = '1-30'
            elif days_overdue <= 60:
                key = '31-60'
            elif days_overdue <= 90:
                key = '61-90'
            else:
                key = '90+'
            buckets[key] += amount
        result = {}
        for key in buckets:
            value = buckets[key]
            if value == 0:
                result[key] = Decimal('0.00')
            else:
                ctx.prec = max(60, value.adjusted() + 8)
                quantized = value.quantize(Decimal('0.01'))
                if quantized == 0:
                    quantized = Decimal('0.00')
                result[key] = quantized
    return result
